def fig(d, f): d['figure'] = f[0]; d['es']['figure'] = f[1]; return d
def boss(d): d['tags'] = ['boss', 'boss6']; return d
def line(points, xlabel, ylabel, xticks, es_x, es_y):
    base = dict(type='line', xmin=0, xmax=xticks[-1], ymin=0, ymax=100, xticks=xticks, yticks=[0, 25, 50, 75, 100], points=points)
    return (dict(base, xlabel=xlabel, ylabel=ylabel), dict(base, xlabel=es_x, ylabel=es_y))
